import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Contributing focused changes","description":"","frontmatter":{"title":"Contributing focused changes","docId":"developer.contributing","translationKey":"developer.contributing","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","translationRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","order":230},"headers":[],"relativePath":"en/developer/contributing.md","filePath":"en/developer/contributing.md","lastUpdated":1794611623000}'),s={name:"en/developer/contributing.md"};function r(o,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="contributing-focused-changes" tabindex="-1">Contributing focused changes <a class="header-anchor" href="#contributing-focused-changes" aria-label="Permalink to &quot;Contributing focused changes {#contributing-focused-changes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Prepare a change that another contributor can review and verify. Read the repository&#39;s <a href="https://github.com/nglmercer/TikTools-app/blob/remake/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>, applicable <code>AGENTS.md</code> files and <a href="./setup.html">setup</a> before editing. Use Bun 1.4.4, Rust 1.95 or newer where needed, committed lockfiles and a branch based on the intended target.</p><h2 id="define-and-implement-the-change" tabindex="-1">Define and implement the change <a class="header-anchor" href="#define-and-implement-the-change" aria-label="Permalink to &quot;Define and implement the change {#define-and-implement-the-change}&quot;">​</a></h2><ol><li>Inspect <code>git status</code> and preserve work owned by others. Keep generated assets, credentials and local databases out of the patch.</li><li>Follow the current source owner: Rust core for service behavior, Control API modules for contracts, typed client for SDK coverage, and the <a href="./frontend.html">frontend layer map</a> for presentation.</li><li>For a contract change, update its canonical definition and regenerate derived output together. Do not hand-maintain another complete RPC or event schema table.</li><li>Keep plugin-specific implementations in their external plugin packages; generic host code should discover manifests rather than import a named plugin.</li><li>Explain the concrete trigger and resulting behavior, including incomplete or experimental paths.</li></ol><h2 id="validate-proportionately" tabindex="-1">Validate proportionately <a class="header-anchor" href="#validate-proportionately" aria-label="Permalink to &quot;Validate proportionately {#validate-proportionately}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>Native implementation changes also need the applicable Rust format/lint/tests and required CI gates. A documentation-only change should use docs checks and review its commands/source links rather than claim native runtime acceptance. The project task runner owns supported entry points; use the Cargo passthrough for specific native target flags.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>The review contains focused source changes, meaningful validation evidence and honest limits. Repository policy targets pull requests into <code>remake</code>; release tags are maintainer controlled. Contribution instructions are available, but branch protection and remote check configuration are administrator responsibilities rather than guarantees made by a Markdown page.</p><h2 id="recover" tabindex="-1">Recover <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Recover {#recover}&quot;">​</a></h2><p>If validation fails because a dependency or platform library is missing, report and repair that environment rather than weakening a check. If generated files drift, regenerate from their owner and inspect the diff. Never publish session cookies, keys, credentials or unsanitized event captures. If source and a legacy design disagree, describe the discrepancy and use current implementation for public guidance. Do not overwrite another owner&#39;s pending files to make a broad cleanup look consistent.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Review stamps have separate meanings: <code>sourceRevision</code> hashes the current English body, while <code>translationRevision</code> hashes this article’s localized body (frontmatter removed, outer whitespace trimmed). After reviewing source and all translations, run <code>bun docs/scripts/record-review.ts developer/example.md</code>. A later edit to either body invalidates the appropriate stamp. This detects drift, not human identity or semantic equivalence: compare commands, RPC/environment identifiers, payload keys, limits, activation/recovery steps and negations explicitly. Translate prose fully while preserving technical instructions.</p><p>For a split migration, record each original topic/heading and its concrete replacement destination in the migration map; include a heading fragment when the destination is a specific section. The checker validates existing files/fragments and exact archived bytes; editorial review must still establish thematic coverage. Never edit historical originals or their provenance to make a migration pass.</p>`,15)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
